import express from "express";
import morgan from "morgan";
import { createRequire } from "module";
import { computeTotal } from "./orders.js";
const require = createRequire(import.meta.url);
const { version } = require("../package.json");
const app = express();
app.use(morgan("combined"));
app.use(express.json());
app.get("/health", (_req, res) => res.json({ ok: true, version }));
app.post("/orders/total", (req, res) => res.json({ total: computeTotal(req.body.items || []) }));
if (process.env.NODE_ENV !== "test") app.listen(3000, () => console.log("orders api on 3000"));
export default app;

import { test } from "node:test";
import assert from "node:assert/strict";
import { computeTotal, formatMoney } from "../lib/orders.js";
test("total with tax", () => { assert.equal(computeTotal([{ price: 10, qty: 2 }]), 24); });
test("discount over 100", () => { assert.equal(computeTotal([{ price: 60, qty: 2 }]), 132); });
test("formatMoney", () => { assert.equal(formatMoney(3.5), "$3.50"); });
test("formatMoney thousands", () => { assert.equal(formatMoney(1234.5), "$1,234.50"); });

